//! Type definitions for this service's operation stubs.
//!
//! @generated by the emulator core scaffold op-stub generator.
//! Each structure/union is declared exactly once. A shape reached by more than
//! one operation lives in `shared_types`; a shape only one operation reaches
//! lives in `<operation>_types`. Every submodule is re-exported here, so
//! `use super::types::*` resolves a type wherever it lives.
//!
//! The `_types` suffix keeps these submodule names disjoint from the operation
//! module names: `ops/mod.rs` declares `pub mod types;` beside one
//! `pub mod <operation>;` per operation and glob-re-exports both, so a submodule
//! here named after an operation would make that operation's own module name
//! ambiguous inside `ops` (`E0659`).

// The schema/serializer macros the `Deployment` and `DeploymentEvent` shapes use, because
// the vendored codegen drops `@timestampFormat("date-time")` from the member schemas it
// builds. Hand-added, not generated; see the module's own note. `#[macro_use]`, and
// declared FIRST, so the macros are in the textual scope of every `*_types` module below.
#[macro_use]
pub mod deployment_wire;

// The `ExperimentDefinition` shape's member list, stated once against the macros above for
// the three operations that answer that shape. Hand-added, not generated; `#[macro_use]`
// and declared before the `*_types` modules that carry those structs, for the same reason.
#[macro_use]
pub mod experiment_definition_wire;

// The `ExperimentRun` shape's member list, stated once against the same macros for the four
// operations that answer that shape. Hand-added, not generated; `#[macro_use]` and declared
// before the `*_types` modules that carry those structs, for the same reason.
#[macro_use]
pub mod experiment_run_wire;

